小月的十六进制一开始的错解一开始没看数据，企图直接用atoi。当然改成atoll和long long这题也是过不去的，这个是错解。
#include &lt;bits/stdc++.h&gt;using namespace std;#define ll long longint main()&#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);        string x;    cin &gt;&gt; x;    int k,num;    cin &gt;&gt; k;    int dec=stoi(x, nullptr, 16);    num=pow(2,k);    if(dec%num==0)&#123;        cout &lt;&lt; &quot;YES&quot;;    &#125;    else&#123;        cout &lt;&lt; &quot;NO&quot;;    &#125;        return 0;&#125;

正确方式十六进制的基数是2^4，也就是说每个十六进制位会对应4个二进制位。想让一个数被2的k次幂整除，当且仅当这个数的二进制表示的末尾有至少k个0。
那如何算这个数的二进制形式末尾有多少个0呢！？
首先，刚刚说过了，一个十六进制位对应4个二进制位，所以十六进制数末尾有一个0，相当于二进制数的末尾有4个0。假设十六进制数末尾有m个0，那么他就贡献了4*m个0。
然后去找第一个非零位。如果这个数可以被2整除n次，我们就称他贡献了n个0。
那么此刻问题就转换成了，判断4*m+n是否大于等于k
#include &lt;bits/stdc++.h&gt;using namespace std;int main()&#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);        string x;    int k;    cin &gt;&gt; x &gt;&gt; k;        if (k == 0) &#123;        cout &lt;&lt; &quot;YES&quot; &lt;&lt; endl;        return 0;    &#125;    int zero=0;    int n=x.size();    char s;    for(int i=n-1;i&gt;=0;i--)&#123;        if(x[i]==&#x27;0&#x27;)&#123;            zero++;        &#125;        else&#123;            s=x[i];            break;        &#125;    &#125;    if(zero==n)&#123;        cout &lt;&lt; &quot;YES&quot;;        return 0;    &#125;    zero*=4;    int num;    if(s&gt;&#x27;0&#x27; &amp;&amp; s&lt;=&#x27;9&#x27;)&#123;        num=s-&#x27;0&#x27;;    &#125;    else if(s&gt;=&#x27;a&#x27; &amp;&amp; s&lt;=&#x27;f&#x27;)&#123;        num=s-&#x27;a&#x27;+10;    &#125;    else&#123;        num=s-&#x27;A&#x27;+10;    &#125;    while(num&gt;0 &amp;&amp; num%2==0)&#123;        zero++;        num/=2;    &#125;    if(zero&gt;=k)&#123;        cout &lt;&lt; &quot;YES&quot;;    &#125;    else&#123;        cout &lt;&lt; &quot;NO&quot;;    &#125;        return 0;&#125;

小月的对局如果Bob想赢，那么无论Alice按什么顺序出牌，Bob都要给每一张Alice的牌配上一张互质的牌，并且每张牌只用一次。
那么问题就变成了，对于Alice的每张牌，Bob是否可以找到对应的牌与它互质。如果可以的话Bob胜利，反之Alice胜利。
那么就变成了二分图的匹配问题喵。
左边n个点是Alice的牌，右边n个点是Bob的牌。如果gcd(a[i],b[j])&#x3D;&#x3D;1，就在i和j之间连边。
然后求最大匹配，如果最大匹配等于n，Bob赢，反之Alice赢。
#include &lt;bits/stdc++.h&gt;using namespace std;#define ll long longint main()&#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);    int n;    cin &gt;&gt; n;    vector&lt;vector&lt;int&gt;&gt; g(n);    vector&lt;int&gt; match(n,-1);    vector&lt;bool&gt; vis(n);    vector&lt;int&gt; a(n);    vector&lt;int&gt; b(n);    for(int i=0;i&lt;n;i++) cin &gt;&gt; a[i];    for(int i=0;i&lt;n;i++) cin &gt;&gt; b[i];    for(int i=0;i&lt;n;i++)&#123;        for(int j=0;j&lt;n;j++)&#123;            if(__gcd(a[i],b[j])==1)&#123;                g[i].push_back(j);            &#125;        &#125;    &#125;    function&lt;bool(int)&gt; dfs=[&amp;](int u)-&gt;bool&#123;        for(int v:g[u])&#123;            if(vis[v]) continue;            vis[v]=true;            if(match[v]==-1 || dfs(match[v]))&#123;                match[v]=u;                return true;            &#125;        &#125;        return false;    &#125;;    int cnt=0;    for(int i=0;i&lt;n;i++)&#123;        fill(vis.begin(),vis.end(),false);        if(dfs(i)) cnt++;    &#125;    if(cnt==n) cout &lt;&lt; &quot;Bob&quot;;    else cout &lt;&lt; &quot;Alice&quot;;            return 0;&#125;

小月的地砖重点就在于如何安排，可以让每一列中的1尽量均匀。
我们把第i个1放到第i%m列里，这样之后每列的1只有可能有两种情况：

⌊S &#x2F; m⌋

⌊S &#x2F; m⌋ + 1


#include &lt;bits/stdc++.h&gt;using namespace std;#define ll long longint main()&#123;    ios::sync_with_stdio(false);    cin.tie(nullptr);        int n,m;    cin &gt;&gt; n &gt;&gt; m;    vector&lt;int&gt; a(n);    for(int i=0;i&lt;n;i++) cin &gt;&gt; a[i];    int cur=0;    for(int i=0;i&lt;n;i++)&#123;        string row(m,&#x27;0&#x27;);        for(int j=0;j&lt;a[i];j++)&#123;            row[cur]=&#x27;1&#x27;;            cur=(cur+1)%m;        &#125;        cout &lt;&lt; row &lt;&lt;&#x27;\n&#x27;;    &#125;        return 0;&#125;
